// media-editor capture feature — camera photo/video capture, permission
// flows, shutter control, multi-instance guard (P3 S3 feature-slicing).
//
// Injected into the base via `capture={mediaCapture}` (MediaEditorProps —
// see `../../hooks/use-capture-extension.ts`). Ships as its own registry
// item, `@ilinxa/media-editor-capture`, with a `registryDependencies: [
// "@ilinxa/media-editor"]` back onto the base.
//
// Re-exports every symbol the base barrel (../../index.ts) dropped when this
// slice was extracted — pre-split `@ilinxa/media-editor` imports of these
// names now resolve here instead. `validateGalleryFile` is the one
// exception: it's generic file-intake, not a capture concern, so it stayed
// (and remains exported from) the base.

import type { MediaCaptureExtension } from "../../hooks/use-capture-extension";
import { MediaCaptureProvider } from "./provider";

/** Pass straight through: `<MediaEditor capture={mediaCapture} />`. */
export const mediaCapture: MediaCaptureExtension = {
  Provider: MediaCaptureProvider,
};

export { MediaCaptureProvider } from "./provider";

export {
  useMediaCapture,
  suggestedVideoFilename,
  type UseMediaCaptureOptions,
  type UseMediaCaptureResult,
  type CapturedPhoto,
  type CapturedVideo,
  type CaptureStatus,
  type FacingMode,
} from "./hooks/use-media-capture";

export {
  useCameraPermissions,
  type CameraPermissionState,
  type UseCameraPermissionsResult,
} from "./hooks/use-camera-permissions";

export { useMultiInstanceGuard } from "./hooks/use-multi-instance-guard";

export { EditorCamera } from "./parts/editor-camera";
export type { EditorCameraProps } from "./parts/editor-camera";

export { CameraPermissionPrompt } from "./parts/camera-permission-prompt";
export { ShutterButton } from "./parts/shutter-button";

// @ilinxa/media-editor-capture 0.6.0

"use client";

import * as React from "react";
import { MediaCaptureExtensionContext } from "../../hooks/use-capture-extension";
import { EditorCamera } from "./parts/editor-camera";

/**
 * Supplies the base orchestrator with the capture feature's camera surface
 * via context (renderer-registry style — the base never statically imports
 * this folder; see `hooks/use-capture-extension.ts`). Thin by design:
 * capture's own state (permissions, live stream, recording, multi-instance
 * guard) lives inside `EditorCamera` itself, so there's nothing else to hold
 * here today.
 */
export function MediaCaptureProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ CameraSurface: EditorCamera }), []);
  return (
    <MediaCaptureExtensionContext.Provider value={value}>
      {children}
    </MediaCaptureExtensionContext.Provider>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type RefObject,
} from "react";
import {
  containerFor,
  selectRecorderMime,
} from "../../../lib/mime-fallback";

export type CaptureStatus =
  | "idle"
  | "acquiring"
  | "ready"
  | "denied"
  | "no-camera"
  | "error";

export type FacingMode = "user" | "environment";

export interface CapturedPhoto {
  blob: Blob;
  width: number;
  height: number;
  mimeType: string;
}

export interface CapturedVideo {
  blob: Blob;
  durationMs: number;
  mimeType: string;
}

export interface UseMediaCaptureOptions {
  /** Enabled while the composer is open; releasing flips back to "idle". */
  enabled: boolean;
  /** Initial camera facing. Auto-detected from UA touch capability if undefined. */
  defaultFacing?: FacingMode;
  /**
   * Request an audio track alongside the video. Default false.
   *
   * **Critical:** only set true when the consumer actually needs audio
   * (i.e. video-mode recording). Photo / text capture should always pass
   * false — requesting mic permission for photo capture is the leading
   * cause of the v0.1.3 flicker-loop: if the user grants camera but
   * denies mic, getUserMedia({audio:true}) rejects, status becomes
   * "denied", the auto-retry effect re-fires, repeat.
   */
  requestAudio?: boolean;
  /** Hard cap on a single recording in seconds. Default 30. */
  maxVideoDurationSec?: number;
  /**
   * When true (default), automatically call `acquire()` on mount and when
   * `enabled` flips on. Set to false to require an explicit user gesture
   * (e.g. a "Tap to enable camera" button) before the camera starts —
   * recommended when the user hasn't previously granted permission, since
   * browser permission prompts are jarring without a triggering interaction.
   */
  autoAcquire?: boolean;
  /**
   * Allowed recording formats in preference order (`videoOutput.mimeTypes`).
   * Default: the built-in chain (WebM VP9 -> VP8 -> MP4).
   */
  videoMimeTypes?: string[];
}

export interface UseMediaCaptureResult {
  videoRef: RefObject<HTMLVideoElement | null>;
  status: CaptureStatus;
  facing: FacingMode;
  error: Error | null;
  /** True when ≥2 video input devices are enumerated (controls switch-camera visibility). */
  canSwitchCamera: boolean;
  /** Currently active MediaStream (null until "ready"). Used by MediaRecorder. */
  stream: MediaStream | null;
  /** Re-acquire the camera (after permission grant or facing change). */
  acquire: () => Promise<void>;
  /** Stop tracks + release the stream. */
  release: () => void;
  /**
   * Snap a still frame from the current video preview.
   *
   * When `aspectRatio` is provided, the captured frame is center-cropped to
   * match — mirroring the CSS `object-cover` crop the user saw in the
   * preview. Pass the dialog/viewport aspect (e.g. `9/16`) to keep
   * what-you-see-is-what-you-get parity; pass `null`/omit to capture the
   * full native frame.
   */
  takePhoto: (opts?: { aspectRatio?: number | null }) => Promise<CapturedPhoto>;
  /** Flip facingMode and re-acquire. */
  switchCamera: () => Promise<void>;
  // ─── Video recording ──────────────────────────────────────────────────
  isRecording: boolean;
  /** Elapsed recording time in ms (updates ~10×/s). */
  recordingMs: number;
  /** Selected MIME type — null if MediaRecorder is unsupported. */
  recorderMime: string | null;
  /** Begin recording. Throws if no stream or no supported codec. */
  startRecording: () => Promise<void>;
  /** Stop recording and return the assembled blob + duration. */
  stopRecording: () => Promise<CapturedVideo>;
}

function isTouchUA(): boolean {
  if (typeof window === "undefined") return false;
  return (
    "ontouchstart" in window ||
    (navigator.maxTouchPoints ?? 0) > 0 ||
    /Android|iPhone|iPad|Mobile/i.test(navigator.userAgent)
  );
}

/**
 * getUserMedia + photo-capture lifecycle.
 *
 * C4 surface: acquire / release / takePhoto / switchCamera.
 * C5 will extend with startRecording / stopRecording.
 */
export function useMediaCapture(
  options: UseMediaCaptureOptions,
): UseMediaCaptureResult {
  const {
    enabled,
    defaultFacing,
    requestAudio = false,
    maxVideoDurationSec = 30,
    autoAcquire = true,
    videoMimeTypes,
  } = options;
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [status, setStatus] = useState<CaptureStatus>("idle");
  const [error, setError] = useState<Error | null>(null);
  const [facing, setFacing] = useState<FacingMode>(
    defaultFacing ?? (isTouchUA() ? "environment" : "user"),
  );
  const [canSwitchCamera, setCanSwitchCamera] = useState(false);

  // ─── Recording state ────────────────────────────────────────────────
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordStartedAtRef = useRef<number>(0);
  const tickIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const autoStopTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stopResolverRef = useRef<{
    resolve: (v: CapturedVideo) => void;
    reject: (e: Error) => void;
  } | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingMs, setRecordingMs] = useState(0);
  // Recorder MIME probed on the client (SSR yields null; selectRecorderMime is
  // a deterministic capability check). The allow-list (`videoMimeTypes`, in
  // preference order) is keyed by content so an inline array literal does not
  // re-probe every render; "|" cannot occur in a MIME type.
  const mimeKey = videoMimeTypes?.join("|") ?? "";
  const recorderMime = useMemo<string | null>(
    () =>
      typeof window === "undefined"
        ? null
        : selectRecorderMime(mimeKey ? mimeKey.split("|") : undefined),
    [mimeKey],
  );

  // Acquire epoch — a monotonically increasing token claimed per acquire().
  // getUserMedia can resolve long after release()/unmount/a competing acquire
  // (permission prompt open, slow device): a resolve under a stale epoch must
  // stop its tracks and bail instead of orphaning a live camera stream (LED
  // stays on) or clobbering the newer acquire's stream. (Review 5.11.)
  const acquireEpochRef = useRef(0);

  const release = useCallback(() => {
    // Invalidate any in-flight acquire before stopping the current stream.
    acquireEpochRef.current += 1;
    const s = streamRef.current;
    if (s) {
      for (const track of s.getTracks()) track.stop();
      streamRef.current = null;
    }
    setStream(null);
    setStatus("idle");
  }, []);

  // Shared acquire pipeline. `nextFacing` is explicit so switchCamera doesn't
  // depend on the (stale-closure-prone) `facing` state committing first.
  const acquireWith = useCallback(
    async (nextFacing: FacingMode) => {
      if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
        setStatus("no-camera");
        setError(new Error("MediaDevices.getUserMedia is not supported"));
        return;
      }
      // Release any prior stream before re-acquiring (switch-camera flow,
      // photo↔video mode flip), then claim a fresh epoch.
      release();
      const epoch = ++acquireEpochRef.current;
      setStatus("acquiring");
      setError(null);
      try {
        const next = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { ideal: nextFacing } },
          audio: requestAudio,
        });
        if (epoch !== acquireEpochRef.current) {
          // Superseded (released / re-acquired / unmounted) while the prompt
          // or device was pending — don't adopt, don't leak.
          for (const track of next.getTracks()) track.stop();
          return;
        }
        streamRef.current = next;
        setStream(next);
        setStatus("ready");

        // Enumerate devices to decide if switch-camera should be offered.
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          if (epoch === acquireEpochRef.current) {
            setCanSwitchCamera(
              devices.filter((d) => d.kind === "videoinput").length >= 2,
            );
          }
        } catch {
          if (epoch === acquireEpochRef.current) setCanSwitchCamera(false);
        }
      } catch (err) {
        if (epoch !== acquireEpochRef.current) return; // stale failure — a newer acquire owns the status
        const e = err as DOMException;
        if (e?.name === "NotAllowedError" || e?.name === "SecurityError") {
          setStatus("denied");
        } else if (e?.name === "NotFoundError") {
          setStatus("no-camera");
        } else {
          setStatus("error");
        }
        setError(err as Error);
      }
    },
    [requestAudio, release],
  );

  const acquire = useCallback(() => acquireWith(facing), [acquireWith, facing]);

  // Auto-acquire on mount when enabled AND autoAcquire is allowed; release
  // on unmount / disable. When autoAcquire is false the consumer is expected
  // to call `acquire()` in response to an explicit user gesture (avoids
  // jarring permission prompts on first paint).
  useEffect(() => {
    if (!enabled) {
      // External-system sync (camera hardware): release() stops the live
      // MediaStream tracks and mirrors the result into state. The epoch
      // invalidation + track teardown + state reset must stay one atomic
      // chokepoint — splitting the state writes out of the effect would fork
      // the acquire-cancellation logic (v0.1.4 fix).
      // eslint-disable-next-line react-hooks/set-state-in-effect
      release();
      return;
    }
    if (autoAcquire) void acquire();
    return release;
    // We don't add `acquire` to deps directly because it changes when facing
    // flips (handled by switchCamera). But we DO depend on `requestAudio` so
    // toggling photo↔video correctly releases + re-acquires with/without an
    // audio track (without it, video mode would inherit a video-only stream
    // from a prior photo-mode acquire and record silent video).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, requestAudio, release, autoAcquire]);

  // Attach the stream to <video>. The <video> tag will be null on first render
  // (rendered in composer-camera), so this fires whenever stream becomes ready.
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    if (stream) {
      v.srcObject = stream;
      v.play().catch(() => {
        /* autoplay may be blocked; ignore — user gesture will unblock */
      });
    } else {
      v.srcObject = null;
    }
  }, [stream]);

  const switchCamera = useCallback(async () => {
    const next: FacingMode = facing === "user" ? "environment" : "user";
    setFacing(next);
    // acquireWith takes the target facing explicitly, so there's no
    // stale-closure microtask dance — and its epoch guard means a rapid
    // double-flip can't interleave two live streams. (Review 5.11.)
    await acquireWith(next);
  }, [facing, acquireWith]);

  // ─── Recording controls ─────────────────────────────────────────────

  const clearRecordingTimers = useCallback(() => {
    if (tickIntervalRef.current) {
      clearInterval(tickIntervalRef.current);
      tickIntervalRef.current = null;
    }
    if (autoStopTimeoutRef.current) {
      clearTimeout(autoStopTimeoutRef.current);
      autoStopTimeoutRef.current = null;
    }
  }, []);

  const startRecording = useCallback(async () => {
    const s = streamRef.current;
    if (!s) throw new Error("Camera not ready");
    // Defensive re-probe if the lazy init yielded null (matches the old
    // ref-cached behavior — selectRecorderMime is deterministic, so a null
    // here re-probes to null and throws below).
    const mime = recorderMime ?? selectRecorderMime(mimeKey ? mimeKey.split("|") : undefined);
    if (!mime) {
      throw new Error("This browser does not support video recording");
    }
    if (recorderRef.current) return; // already recording

    const rec = new MediaRecorder(s, { mimeType: mime });
    recorderRef.current = rec;
    chunksRef.current = [];
    rec.ondataavailable = (ev) => {
      if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data);
    };
    rec.onstop = () => {
      const durationMs = Date.now() - recordStartedAtRef.current;
      const blob = new Blob(chunksRef.current, { type: mime });
      const resolver = stopResolverRef.current;
      stopResolverRef.current = null;
      recorderRef.current = null;
      chunksRef.current = [];
      clearRecordingTimers();
      setIsRecording(false);
      setRecordingMs(0);
      resolver?.resolve({ blob, durationMs, mimeType: mime });
    };
    rec.onerror = (ev) => {
      const e =
        (ev as unknown as { error?: Error }).error ??
        new Error("MediaRecorder failed");
      const resolver = stopResolverRef.current;
      stopResolverRef.current = null;
      recorderRef.current = null;
      chunksRef.current = [];
      clearRecordingTimers();
      setIsRecording(false);
      setRecordingMs(0);
      resolver?.reject(e);
    };

    recordStartedAtRef.current = Date.now();
    setRecordingMs(0);
    setIsRecording(true);
    rec.start(250); // 250ms timeslice — smooth UI ticks

    // Tick recording time for UI
    tickIntervalRef.current = setInterval(() => {
      setRecordingMs(Date.now() - recordStartedAtRef.current);
    }, 100);

    // Hard cap auto-stop
    autoStopTimeoutRef.current = setTimeout(
      () => {
        if (recorderRef.current?.state === "recording") {
          recorderRef.current.stop();
        }
      },
      maxVideoDurationSec * 1000,
    );
  }, [clearRecordingTimers, maxVideoDurationSec, recorderMime, mimeKey]);

  const stopRecording = useCallback((): Promise<CapturedVideo> => {
    const rec = recorderRef.current;
    if (!rec || rec.state !== "recording") {
      return Promise.reject(new Error("Not recording"));
    }
    return new Promise<CapturedVideo>((resolve, reject) => {
      stopResolverRef.current = { resolve, reject };
      rec.stop();
    });
  }, []);

  // Cleanup any in-flight recording when stream is released / hook unmounts.
  useEffect(() => {
    return () => {
      const rec = recorderRef.current;
      if (rec && rec.state !== "inactive") {
        try {
          rec.stop();
        } catch {
          /* ignore */
        }
      }
      recorderRef.current = null;
      chunksRef.current = [];
      clearRecordingTimers();
    };
  }, [clearRecordingTimers]);

  const takePhoto = useCallback(
    async (opts?: { aspectRatio?: number | null }): Promise<CapturedPhoto> => {
      const v = videoRef.current;
      if (!v || !streamRef.current) {
        throw new Error("Camera not ready");
      }
      const nativeW = v.videoWidth;
      const nativeH = v.videoHeight;
      if (nativeW === 0 || nativeH === 0) {
        throw new Error("Video has no frame yet");
      }

      // Determine the source-rect to capture. With aspectRatio provided, we
      // center-crop the native frame to match — mirroring CSS object-cover:
      // scale-to-fill + center-crop. videoAspect > target → crop horizontal;
      // videoAspect < target → crop vertical; equal → no crop.
      const target =
        opts?.aspectRatio && opts.aspectRatio > 0 ? opts.aspectRatio : null;
      let sx = 0;
      let sy = 0;
      let sw = nativeW;
      let sh = nativeH;
      if (target !== null) {
        const videoAspect = nativeW / nativeH;
        if (videoAspect > target) {
          // Video is wider than target — crop horizontal sides.
          sw = nativeH * target;
          sx = (nativeW - sw) / 2;
        } else if (videoAspect < target) {
          // Video is taller than target — crop top/bottom.
          sh = nativeW / target;
          sy = (nativeH - sh) / 2;
        }
      }

      const outW = Math.round(sw);
      const outH = Math.round(sh);
      const canvas = document.createElement("canvas");
      canvas.width = outW;
      canvas.height = outH;
      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("2D canvas context unavailable");
      ctx.drawImage(v, sx, sy, sw, sh, 0, 0, outW, outH);
      const blob: Blob = await new Promise((resolve, reject) => {
        canvas.toBlob(
          (b) => (b ? resolve(b) : reject(new Error("toBlob returned null"))),
          "image/jpeg",
          0.92,
        );
      });
      return { blob, width: outW, height: outH, mimeType: "image/jpeg" };
    },
    [],
  );

  return {
    videoRef,
    status,
    facing,
    error,
    canSwitchCamera,
    stream,
    acquire,
    release,
    takePhoto,
    switchCamera,
    isRecording,
    recordingMs,
    recorderMime,
    startRecording,
    stopRecording,
  };
}

/** Suggested filename for a recorded clip — useful for the publish step. */
export function suggestedVideoFilename(mime: string): string {
  // now-ok: builds a filename on demand (called from publish handlers); never reaches markup
  return `story-${Date.now()}.${containerFor(mime) === "unknown" ? "bin" : containerFor(mime)}`;
}

// `validateGalleryFile` moved to the BASE (P3 S3 — it's generic file-intake,
// not a capture concern) — see `../../../lib/validate-media-file.ts`.
// `parts/editor-camera.tsx` imports it directly from there.

"use client";

import { useCallback, useEffect, useState } from "react";

export type CameraPermissionState =
  | "unknown"
  | "prompt"
  | "granted"
  | "denied";

export interface UseCameraPermissionsResult {
  state: CameraPermissionState;
  /** Browser supports the Permissions API for "camera". */
  supported: boolean;
  /** Force a re-check (useful after explicit retry). */
  refresh: () => Promise<void>;
}

/**
 * Watches `navigator.permissions.query({ name: "camera" })` and auto-updates
 * on settings changes (Chrome / Firefox / Edge). Safari has no Permissions
 * API for camera; we expose `supported=false` and consumers fall back to
 * trying `getUserMedia` directly to discover the permission state.
 */
export function useCameraPermissions(): UseCameraPermissionsResult {
  const [state, setState] = useState<CameraPermissionState>("unknown");
  const [supported, setSupported] = useState(false);
  // Held in STATE (not a ref) so the change-listener effect below re-binds to
  // each PermissionStatus a refresh() yields — binding only the first one left
  // later statuses unwatched.
  const [status, setStatusObj] = useState<PermissionStatus | null>(null);

  const refresh = useCallback(async () => {
    if (typeof navigator === "undefined" || !navigator.permissions?.query) {
      setSupported(false);
      setState("unknown");
      return;
    }
    try {
      // `camera` is in the Permissions spec but TS lib.dom doesn't list it.
      const next = await navigator.permissions.query({
        name: "camera" as PermissionName,
      });
      setStatusObj(next);
      setSupported(true);
      setState(next.state as CameraPermissionState);
    } catch {
      // Safari throws TypeError for "camera"
      setSupported(false);
      setState("unknown");
    }
  }, []);

  useEffect(() => {
    // Mount-time query of an external system (Permissions API). Every state
    // write lands in refresh()'s async continuation EXCEPT the
    // no-Permissions-API guard, whose synchronous writes equal the initial
    // state (supported=false / "unknown") — a bail-out no-op on mount.
    // Restructuring to useSyncExternalStore would fork the status-in-state
    // listener-rebind fix (see the `status` state comment above).
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!status) return;
    const handler = () => setState(status.state as CameraPermissionState);
    status.addEventListener("change", handler);
    return () => status.removeEventListener("change", handler);
  }, [status]);

  return { state, supported, refresh };
}

"use client";

import { useEffect } from "react";

/**
 * Multi-instance guard — fires a dev-only `console.warn` when 2+ CAMERA
 * SURFACES are actually mounted at once (Q-P5 lock = `b`). Since the P3
 * capture split the guard lives in `EditorCamera` (gated on its `enabled`
 * prop), so instances merely CONFIGURED for camera no longer warn until a
 * camera surface really mounts — the trigger tracks live-stream contention,
 * the thing being guarded, rather than configuration intent (R4 verdict
 * 2026-08-11; pre-split behavior warned on config alone).
 *
 * Rationale: each instance owns its own `Konva.Stage` — fine, no
 * conflict. But `getUserMedia` against the same physical camera with
 * multiple live streams degrades quickly (most browsers serialize
 * constraints to the first opener, perf cliffs hit fast). The dev-warn
 * catches the layout-builder footgun without blocking valid two-camera
 * UIs the consumer knows what they're doing about.
 *
 * Edit-only instances (no capture mode enabled) bypass the counter
 * unconditionally — per description §1 they have no camera contention
 * to worry about. The caller decides whether to engage the guard via
 * the `enabled` arg.
 *
 * The counter is module-scoped (not React state) so multiple instances
 * across the tree observe the same value. Reset semantics are
 * mount-increment / unmount-decrement; HMR drift is acceptable for a
 * dev-only diagnostic.
 */

let captureInstanceCount = 0;
let warnedAt = -1;

export function useMultiInstanceGuard(enabled: boolean): void {
  useEffect(() => {
    if (!enabled) return;
    if (process.env.NODE_ENV === "production") return;
    captureInstanceCount += 1;
    if (captureInstanceCount >= 2 && warnedAt !== captureInstanceCount) {
      warnedAt = captureInstanceCount;
      console.warn(
        `media-editor: ${captureInstanceCount} capture-enabled instances mounted simultaneously. ` +
          "Multiple live camera previews tend to degrade quickly — consider " +
          "`presentation=\"dialog\"` (one-at-a-time UX) or restricting secondary instances to edit-only " +
          "(`enabledModes` without `photo`/`video`).",
      );
    }
    return () => {
      captureInstanceCount = Math.max(0, captureInstanceCount - 1);
      if (captureInstanceCount < 2) {
        warnedAt = -1;
      }
    };
  }, [enabled]);
}

/**
 * Test-only — reset the module-scoped counter. Not exported via the
 * barrel; used by vitest if it ever lands.
 */
export function __resetMultiInstanceGuard(): void {
  captureInstanceCount = 0;
  warnedAt = -1;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Image as ImageIcon, SwitchCamera } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
// Direct relative imports — NEVER through the base barrel (F-S1 / R1
// VERDICT). `useMediaCapture` / `useCameraPermissions` are co-located in
// this feature; `validateGalleryFile` is generic file-intake and lives in
// BASE (moved there in P3 S3); `useMultiInstanceGuard` is co-located too —
// its call site lives HERE (not in the base orchestrator) since the
// contention it guards against (2+ live camera streams) only exists while a
// camera surface is actually mounted.
import { useMediaCapture, type CapturedPhoto, type CapturedVideo } from "../hooks/use-media-capture";
import { useCameraPermissions } from "../hooks/use-camera-permissions";
import { useMultiInstanceGuard } from "../hooks/use-multi-instance-guard";
import {
  acceptAttribute,
  validateGalleryFile,
} from "../../../lib/validate-media-file";
import { CameraPermissionPrompt } from "./camera-permission-prompt";
import { ShutterButton } from "./shutter-button";
import type {
  ComposerMode,
  MediaEditorResolvedLabels,
  ValidationError,
} from "../../../types";

export interface EditorCameraProps {
  /** Composer is open + we should hold a live camera stream. */
  enabled: boolean;
  /** Drives mirror behavior, default facing, and the shutter aria-label. */
  mode: ComposerMode;
  defaultFacing?: "user" | "environment";
  recordAudio?: boolean;
  maxFileSizeMb?: number;
  maxVideoDurationSec?: number;
  /**
   * Numeric aspect-ratio (width/height) of the visible preview region. When
   * provided, the captured photo is center-cropped to match — mirroring the
   * preview's CSS `object-cover` crop. Pass `null` for free (no crop).
   */
  captureAspectRatio?: number | null;
  /**
   * When true, force auto-acquire of the camera on mount even if browser
   * permission isn't pre-granted — used after an explicit user gesture (e.g.
   * the "Connect to camera" entry button or a mode-tab click) so the
   * subsequent permission prompt fires in the same gesture-credited tick.
   * Default behavior auto-acquires only when `perms.state === "granted"`.
   */
  autoAcquireOverride?: boolean;
  labels: MediaEditorResolvedLabels;
  /** BCP 47 locale for the numbers in validation messages. Default: `"en"`. */
  locale?: string;
  /** Accepted MIME types for the gallery picker and its validator. Default `["image/*", "video/*"]`. */
  acceptMediaTypes?: string[];
  /** Allowed video recording formats in preference order. Default: the built-in chain. */
  videoMimeTypes?: string[];
  onPhoto: (photo: CapturedPhoto) => void;
  onVideo: (video: CapturedVideo) => void;
  /** Loads an image / video file picked from the gallery into the editor. */
  onGalleryFile: (file: File) => void;
  onValidationError?: (error: ValidationError) => void;
  /** Fires when permission is denied so the host can show its own help. */
  onPermissionDenied?: () => void;
  /**
   * Replaces the built-in denied-permission UI. Receives `retry` (re-request
   * the camera) + `usePicker` (open the gallery file picker). Only substitutes
   * the `denied` state — the pending / no-camera / error states keep the
   * built-in prompt.
   */
  renderPermissionDenied?: (ctx: {
    retry: () => void;
    usePicker: () => void;
  }) => React.ReactNode;
}

export function EditorCamera({
  enabled,
  mode,
  defaultFacing,
  recordAudio = true,
  maxFileSizeMb = 50,
  maxVideoDurationSec = 30,
  captureAspectRatio,
  autoAcquireOverride,
  labels,
  locale,
  acceptMediaTypes,
  videoMimeTypes,
  onPhoto,
  onVideo,
  onGalleryFile,
  onValidationError,
  onPermissionDenied,
  renderPermissionDenied,
}: EditorCameraProps) {
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [busy, setBusy] = useState(false);

  // Multi-instance guard (moved from the base orchestrator in P3 S3 — see
  // import comment above). Gated on `enabled`, which mirrors the original
  // `cameraIntakeAvailable` intent closely enough: this component only
  // mounts while the editor actually wants a live camera surface, so the
  // guard now fires exactly while camera contention could occur, rather than
  // merely "configured for camera" (a slightly tighter, arguably more
  // accurate trigger window than the pre-split behavior).
  useMultiInstanceGuard(enabled);

  const perms = useCameraPermissions();
  // Only request mic permission for video mode — requesting audio in photo
  // mode caused the v0.1.3 flicker loop (user might have mic denied while
  // camera is granted; getUserMedia rejects → status flips → auto-retry).
  const requestAudio = mode === "video" && recordAudio;
  // Auto-acquire only if the browser has already granted camera permission;
  // otherwise wait for an explicit user gesture (the "Enable camera" button
  // on the idle prompt). Avoids surprising users with a permission prompt
  // the moment they open the composer.
  // Destructure the hook result to locals up front. `videoRef` is a ref-typed
  // field; passing `capture.videoRef` as a JSX ref makes the React Compiler's
  // aliasing analysis treat the whole result object as a ref container and
  // flag every later `capture.*` read as "ref access during render" (known
  // false-positive class — same fix as story-viewer/reply-composer).
  const {
    videoRef,
    status: captureStatus,
    facing: captureFacing,
    canSwitchCamera,
    acquire,
    takePhoto,
    switchCamera,
    isRecording,
    recordingMs,
    startRecording,
    stopRecording,
  } = useMediaCapture({
    enabled,
    defaultFacing,
    requestAudio,
    maxVideoDurationSec,
    videoMimeTypes,
    autoAcquire: autoAcquireOverride || perms.state === "granted",
  });

  // Surface permission-denied to the consumer once.
  const deniedFiredRef = useRef(false);
  useEffect(() => {
    if (captureStatus === "denied" && !deniedFiredRef.current) {
      deniedFiredRef.current = true;
      onPermissionDenied?.();
    } else if (captureStatus !== "denied") {
      deniedFiredRef.current = false;
    }
  }, [captureStatus, onPermissionDenied]);

  // Front-camera preview is mirrored to match user expectation; rear is not.
  const mirrored = captureFacing === "user";

  const handleShutterPhoto = async () => {
    if (busy || captureStatus !== "ready") return;
    setBusy(true);
    try {
      const photo = await takePhoto({
        aspectRatio: captureAspectRatio ?? null,
      });
      onPhoto(photo);
    } catch (err) {
      // No ValidationError kind fits a transient shutter failure (no frame
      // yet / toBlob null) — dev-warn instead of swallowing silently.
      if (process.env.NODE_ENV !== "production") {
        console.warn("media-editor: takePhoto failed", err);
      }
    } finally {
      setBusy(false);
    }
  };

  const handleVideoStart = async () => {
    if (busy || captureStatus !== "ready") return;
    try {
      await startRecording();
    } catch (err) {
      onValidationError?.({
        kind: "unsupported-codec",
        message: labels.videoUnsupported,
      });
      if (process.env.NODE_ENV !== "production") {
        console.warn("media-editor: startRecording failed", err);
      }
    }
  };

  const handleVideoStop = async () => {
    if (!isRecording) return;
    setBusy(true);
    try {
      const video = await stopRecording();
      onVideo(video);
    } catch (err) {
      // A failed stop means the recording is lost — surface it on the same
      // channel handleVideoStart already uses.
      onValidationError?.({
        kind: "unsupported-codec",
        message: labels.videoFailed,
      });
      if (process.env.NODE_ENV !== "production") {
        console.warn("media-editor: stopRecording failed", err);
      }
    } finally {
      setBusy(false);
    }
  };

  const handleGalleryClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = ""; // reset so picking the same file twice re-fires
    if (!file) return;
    const err = validateGalleryFile(file, maxFileSizeMb, {
      labels,
      locale,
      acceptMediaTypes,
    });
    if (err) {
      onValidationError?.(err);
      return;
    }
    onGalleryFile(file);
  };

  // ─── Permission UI ────────────────────────────────────────────────────
  const permissionVariant:
    | null
    | "idle"
    | "pending"
    | "denied"
    | "no-camera"
    | "error" =
    captureStatus === "acquiring"
      ? "pending"
      : captureStatus === "denied"
        ? "denied"
        : captureStatus === "no-camera"
          ? "no-camera"
          : captureStatus === "error"
            ? "error"
            : captureStatus === "idle"
              ? "idle"
              : null;

  // Auto-retry on permission change (Q-P8a) — when the watcher flips to
  // "granted" but our capture is still in "denied", silently re-acquire.
  //
  // BOUNDED — fires AT MOST ONCE per granted-state transition. Without this
  // bound, a stable denial (e.g. mic denied while photo mode requests it)
  // makes acquire() → fail → status="denied" → effect re-fires → infinite
  // loop. Resets when status becomes "ready" so a future denial can retry.
  // Also deps on the destructured captureStatus/acquire locals, not the whole
  // capture result object (which is a fresh ref every render).
  const autoRetryAttemptedRef = useRef(false);
  useEffect(() => {
    if (perms.state === "granted") {
      if (captureStatus === "denied" && !autoRetryAttemptedRef.current) {
        autoRetryAttemptedRef.current = true;
        void acquire();
      } else if (captureStatus === "ready") {
        autoRetryAttemptedRef.current = false;
      }
    } else {
      autoRetryAttemptedRef.current = false;
    }
  }, [perms.state, captureStatus, acquire]);

  // Resolve the permission-overlay body once. The consumer's
  // renderPermissionDenied slot replaces the built-in prompt for the `denied`
  // state only; pending / no-camera / error keep the built-in prompt.
  let permissionOverlay: React.ReactNode = null;
  if (permissionVariant === "denied" && renderPermissionDenied) {
    // `usePicker` reads fileInputRef only when the CONSUMER invokes it from an
    // event handler — never during this render — so the ref-during-render rule
    // is a false positive here (same deferred-invocation contract as the
    // CameraPermissionPrompt `onUsePicker` prop below, which isn't flagged).
    // eslint-disable-next-line react-hooks/refs
    permissionOverlay = renderPermissionDenied({
      retry: () => void acquire(),
      usePicker: handleGalleryClick,
    });
  } else if (permissionVariant !== null) {
    permissionOverlay = (
      <CameraPermissionPrompt
        variant={permissionVariant}
        labels={labels}
        onRetry={() => void acquire()}
        onUsePicker={handleGalleryClick}
      />
    );
  }

  return (
    <div className="@container relative flex-1 flex flex-col overflow-hidden">
      {/* Live preview — black fallback shows when no stream */}
      <video
        ref={videoRef}
        autoPlay
        playsInline
        muted
        className={cn(
          "absolute inset-0 w-full h-full object-cover bg-black",
          mirrored && "scale-x-[-1]",
          permissionVariant !== null && "opacity-0",
        )}
      />

      {/* Permission overlay (denied / pending / no-camera / error). Body
          resolved above — the renderPermissionDenied slot can replace the
          denied state. */}
      {permissionOverlay !== null && (
        <div className="absolute inset-0 flex items-center justify-center bg-black">
          {permissionOverlay}
        </div>
      )}

      {/* Recording indicator — red dot + mm:ss top-center */}
      {isRecording && (
        <div
          role="status"
          aria-live="polite"
          className="absolute top-16 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 rounded-full bg-media-overlay backdrop-blur-md px-3 py-1.5 text-media-overlay-foreground"
        >
          <span className="size-2 rounded-full bg-destructive animate-pulse" />
          <span className="text-xs font-mono tabular-nums">
            {formatRecordingTime(recordingMs)}
          </span>
          <span className="sr-only">{labels.recordingLabel}</span>
        </div>
      )}

      {/* Bottom control row — gallery / shutter / switch-camera */}
      <div
        className={cn(
          "absolute left-0 right-0 z-20 flex items-center justify-between px-6",
          "bottom-[max(1.25rem,env(safe-area-inset-bottom))]",
        )}
      >
        {/* Gallery picker */}
        <Button
          variant="ghost"
          size="icon"
          onClick={handleGalleryClick}
          aria-label={labels.galleryPicker}
          className="size-[clamp(2rem,9cqw,2.5rem)] rounded-full bg-media-overlay backdrop-blur-md text-media-overlay-foreground hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
        >
          <ImageIcon className="size-[55%]" />
        </Button>

        {/* Shutter — photo: tap | video: long-press hold OR tap-to-toggle */}
        <ShutterButton
          mode={mode === "video" ? "video" : "photo"}
          // Sized to the camera width (container query) — not the viewport — so
          // it stays proportional in the dialog / chat embeds instead of
          // ballooning when the browser window is wide.
          className="size-[clamp(2.75rem,15cqw,3.5rem)]"
          onPress={handleShutterPhoto}
          onStart={handleVideoStart}
          onStop={handleVideoStop}
          isRecording={isRecording}
          recordProgress={
            isRecording
              ? Math.min(
                  1,
                  recordingMs / (maxVideoDurationSec * 1000),
                )
              : 0
          }
          disabled={
            busy ||
            captureStatus !== "ready" ||
            mode === "text"
          }
          ariaLabel={
            mode === "video"
              ? isRecording
                ? labels.shutterVideoStop
                : labels.shutterVideoStart
              : labels.shutterPhoto
          }
        />

        {/* Switch camera (only when ≥2 devices) */}
        {canSwitchCamera ? (
          <Button
            variant="ghost"
            size="icon"
            onClick={() => void switchCamera()}
            aria-label={labels.switchCamera}
            className="size-[clamp(2rem,9cqw,2.5rem)] rounded-full bg-media-overlay backdrop-blur-md text-media-overlay-foreground hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
          >
            <SwitchCamera className="size-[55%]" />
          </Button>
        ) : (
          <div className="size-[clamp(2rem,9cqw,2.5rem)]" aria-hidden />
        )}
      </div>

      {/* Hidden file input for gallery pick */}
      <input
        ref={fileInputRef}
        type="file"
        accept={acceptAttribute(acceptMediaTypes)}
        onChange={handleFileChange}
        hidden
        className="hidden"
      />
    </div>
  );
}

function formatRecordingTime(ms: number): string {
  const totalSec = Math.floor(ms / 1000);
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

"use client";

import { Camera, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { MediaEditorResolvedLabels } from "../../../types";

export type PermissionPromptVariant =
  | "idle"
  | "pending"
  | "denied"
  | "no-camera"
  | "error";

export interface CameraPermissionPromptProps {
  variant: PermissionPromptVariant;
  labels: MediaEditorResolvedLabels;
  onRetry: () => void;
  onUsePicker: () => void;
  className?: string;
}

export function CameraPermissionPrompt({
  variant,
  labels,
  onRetry,
  onUsePicker,
  className,
}: CameraPermissionPromptProps) {
  if (variant === "pending") {
    return (
      <div
        className={cn(
          "flex flex-col items-center justify-center gap-3 text-center text-media-overlay-foreground/80 px-6",
          className,
        )}
      >
        <Camera className="size-8 animate-pulse" />
        <p className="text-sm">{labels.permissionRequesting}</p>
      </div>
    );
  }

  if (variant === "idle") {
    return (
      <div
        className={cn(
          "flex flex-col items-center justify-center gap-4 text-center text-media-overlay-foreground px-6 max-w-sm mx-auto",
          className,
        )}
      >
        <Camera className="size-8" />
        <div className="space-y-1.5">
          <p className="text-base font-medium">{labels.permissionIdleTitle}</p>
          <p className="text-sm text-media-overlay-foreground/80 leading-relaxed">
            {labels.permissionIdleBody}
          </p>
        </div>
        <div className="flex flex-col gap-2 w-full">
          <Button
            onClick={onRetry}
            variant="secondary"
            className="bg-media-overlay-foreground text-black hover:bg-media-overlay-foreground/90"
          >
            {labels.permissionEnable}
          </Button>
          <Button
            onClick={onUsePicker}
            variant="ghost"
            className="text-media-overlay-foreground hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
          >
            {labels.permissionUsePicker}
          </Button>
        </div>
      </div>
    );
  }

  const title =
    variant === "no-camera"
      ? labels.permissionNoCameraTitle
      : variant === "error"
        ? labels.permissionErrorTitle
        : labels.permissionDeniedTitle;

  return (
    <div
      role="alert"
      aria-live="polite"
      className={cn(
        "flex flex-col items-center justify-center gap-4 text-center text-media-overlay-foreground px-6 max-w-sm mx-auto",
        className,
      )}
    >
      <AlertTriangle className="size-8 text-warning" />
      <div className="space-y-1.5">
        <p className="text-base font-medium">{title}</p>
        <p className="text-sm text-media-overlay-foreground/80 leading-relaxed">
          {labels.permissionDeniedBody}
        </p>
      </div>
      <div className="flex flex-col gap-2 w-full">
        <Button
          onClick={onRetry}
          variant="secondary"
          className="bg-media-overlay-foreground text-black hover:bg-media-overlay-foreground/90"
        >
          {labels.permissionRetry}
        </Button>
        <Button
          onClick={onUsePicker}
          variant="ghost"
          className="text-media-overlay-foreground hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
        >
          {labels.permissionUsePicker}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useRef, type PointerEvent } from "react";
import { cn } from "@/lib/utils";

export interface ShutterButtonProps {
  mode: "photo" | "video";
  /** Photo-mode tap. Ignored when mode="video". */
  onPress?: () => void;
  /** Video-mode start. Called for both long-press hold and tap-to-start. */
  onStart?: () => void;
  /** Video-mode stop. Called on long-press release OR tap-to-stop. */
  onStop?: () => void;
  /** Recording in-flight (drives ring fill + inner shape). */
  isRecording?: boolean;
  /** 0..1 — fraction of maxVideoDuration elapsed. Drives ring conic-gradient. */
  recordProgress?: number;
  disabled?: boolean;
  ariaLabel: string;
  className?: string;
}

const LONG_PRESS_THRESHOLD_MS = 250;

/**
 * Shutter behavior matrix (Instagram parity):
 *
 *   Mode photo + tap     → onPress
 *   Mode video + tap     → onStart (then a later tap → onStop)
 *   Mode video + hold    → onStart on down, onStop on up
 */
export function ShutterButton({
  mode,
  onPress,
  onStart,
  onStop,
  isRecording = false,
  recordProgress = 0,
  disabled = false,
  ariaLabel,
  className,
}: ShutterButtonProps) {
  const pressStartRef = useRef<number>(0);
  const startedThisPressRef = useRef(false);

  const handlePointerDown = useCallback(
    (e: PointerEvent<HTMLButtonElement>) => {
      if (disabled) return;
      e.currentTarget.setPointerCapture?.(e.pointerId);
      pressStartRef.current = Date.now();
      if (mode === "photo") {
        startedThisPressRef.current = false;
        return;
      }
      if (!isRecording) {
        startedThisPressRef.current = true;
        onStart?.();
      } else {
        startedThisPressRef.current = false;
      }
    },
    [disabled, mode, isRecording, onStart],
  );

  const handlePointerUp = useCallback(
    (e: PointerEvent<HTMLButtonElement>) => {
      if (disabled) return;
      e.currentTarget.releasePointerCapture?.(e.pointerId);
      const elapsed = Date.now() - pressStartRef.current;

      if (mode === "photo") {
        onPress?.();
        return;
      }

      const wasHold = elapsed >= LONG_PRESS_THRESHOLD_MS;
      if (wasHold) {
        onStop?.();
      } else if (!startedThisPressRef.current) {
        // Tap on already-recording shutter → stop (tap-to-toggle stop)
        onStop?.();
      }
      // else: tap started recording this press → leave running (tap-to-toggle start)
      startedThisPressRef.current = false;
    },
    [disabled, mode, onPress, onStop],
  );

  const handlePointerCancel = useCallback(() => {
    // Treat cancellation as a stop if we started recording.
    if (mode === "video" && isRecording && startedThisPressRef.current) {
      onStop?.();
      startedThisPressRef.current = false;
    }
  }, [mode, isRecording, onStop]);

  // Ring fill via conic-gradient when recording.
  const ringStyle =
    mode === "video" && isRecording
      ? {
          background: `conic-gradient(#ef4444 ${recordProgress * 360}deg, rgba(255,255,255,0.3) ${recordProgress * 360}deg)`,
        }
      : undefined;

  return (
    <button
      type="button"
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerCancel}
      disabled={disabled}
      aria-label={ariaLabel}
      aria-pressed={mode === "video" ? isRecording : undefined}
      className={cn(
        // Responsive size — min 48px on narrow viewports, max 68px on wide.
        "relative grid place-items-center size-[clamp(3rem,12vw,4.25rem)] rounded-full",
        "transition-transform active:scale-95",
        "disabled:opacity-40 disabled:cursor-not-allowed",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-media-overlay-foreground focus-visible:ring-offset-2 focus-visible:ring-offset-transparent",
        className,
      )}
      style={ringStyle}
    >
      {/* Outer ring (idle white border; conic on record) */}
      {mode === "video" && isRecording ? (
        // Filled ring is the gradient on the button itself; inner stop-square sits inside
        <span className="grid place-items-center size-[80%] rounded-full bg-media-overlay">
          <span className="size-[36%] rounded-md bg-destructive" />
        </span>
      ) : (
        <span
          className={cn(
            "size-full rounded-full ring-4 ring-media-overlay-foreground/30 ring-offset-2 ring-offset-transparent grid place-items-center",
            "bg-media-overlay-foreground",
          )}
        >
          {mode === "video" ? (
            <span className="size-[30%] rounded-full bg-destructive" />
          ) : null}
        </span>
      )}
      <span className="sr-only">{ariaLabel}</span>
    </button>
  );
}
